[{"order":1,"type":"heading","text":"Dependency Injection (DI) Principles and Patterns in Angular"},{"order":2,"type":"paragraph","text":"Dependency Injection (DI) is a design pattern that promotes loose coupling between software components. In Angular, DI is a core feature that allows you to manage dependencies effectively, making your code more testable, maintainable, and reusable."},{"order":3,"type":"subheading","text":"Principles of Dependency Injection"},{"order":4,"type":"bullet_point","text":"Inversion of Control (IoC): Instead of a component creating its dependencies, the dependencies are provided to the component. Angular's DI framework handles the creation and management of these dependencies."},{"order":5,"type":"bullet_point","text":"Single Responsibility Principle: Each class should have only one reason to change. DI helps achieve this by allowing you to inject different implementations of a dependency without modifying the class itself."},{"order":6,"type":"bullet_point","text":"Open/Closed Principle: Software entities (classes, modules, functions, etc.) should be open for extension, but closed for modification. DI enables you to extend functionality by injecting new dependencies without altering existing code."},{"order":7,"type":"subheading","text":"DI Patterns in Angular"},{"order":8,"type":"paragraph","text":"Angular provides several ways to implement DI. Here are the common patterns:"},{"order":9,"type":"bullet_point","text":"Constructor Injection: The most common and recommended pattern. Dependencies are provided through the class constructor."},{"order":10,"type":"code","text":"import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class MyService {
  constructor() { }

  getData(): string {
    return 'Data from MyService';
  }
}

import { Component } from '@angular/core';
import { MyService } from './my.service';

@Component({
  selector: 'app-my-component',
  template: '<div>{{ data }}</div>',
})
export class MyComponent {
  data: string;

  constructor(private myService: MyService) {
    this.data = this.myService.getData();
  }
}"},{"order":11,"type":"bullet_point","text":"Property Injection: Dependencies are injected directly into class properties using the @Inject decorator. Less common and generally discouraged due to making dependencies less explicit."},{"order":12,"type":"code","text":"import { Component, Inject } from '@angular/core';
import { MyService } from './my.service';

@Component({
  selector: 'app-my-component',
  template: '<div>{{ data }}</div>',
})
export class MyComponent {
  @Inject(MyService)
  myService!: MyService; //Definite assignment assertion
  data: string;

  constructor() {
    this.data = this.myService.getData();
  }
}"},{"order":13,"type":"bullet_point","text":"Setter Injection: Dependencies are injected through setter methods. Similar to property injection, less common than constructor injection."},{"order":14,"type":"code","text":"import { Component } from '@angular/core';
import { MyService } from './my.service';

@Component({
  selector: 'app-my-component',
  template: '<div>{{ data }}</div>',
})
export class MyComponent {
  private _myService!: MyService;
  data: string;

  constructor() {
    this.data = this.myService.getData();
  }

  set myService(service: MyService) {
    this._myService = service;
    this.data = this._myService.getData();
  }

  get myService(): MyService {
    return this._myService;
  }
}"},{"order":15,"type":"subheading","text":"Dependency Injection Tokens"},{"order":16,"type":"paragraph","text":"When injecting interfaces or abstract classes, you need to use DI tokens to tell Angular which implementation to use.  `InjectionToken` is used to provide a token for non-class dependencies."},{"order":17,"type":"code","text":"import { InjectionToken } from '@angular/core';

export const API_URL = new InjectionToken<string>('api.url');

// In a module:
import { NgModule } from '@angular/core';
import { API_URL } from './tokens';

@NgModule({
  providers: [
    { provide: API_URL, useValue: 'https://api.example.com' }
  ]
})
export class AppModule { }"},{"order":18,"type":"subheading","text":"Benefits of Dependency Injection"},{"order":19,"type":"bullet_point","text":"Improved Testability: Easily mock or stub dependencies during unit testing."},{"order":20,"type":"bullet_point","text":"Increased Reusability: Components are less coupled and can be reused in different contexts."},{"order":21,"type":"bullet_point","text":"Enhanced Maintainability: Changes to dependencies have minimal impact on other components."},{"order":22,"type":"bullet_point","text":"Better Code Organization: Promotes a modular and well-structured codebase."},{"order":23,"type":"subheading","text":"Conclusion"},{"order":24,"type":"paragraph","text":"Dependency Injection is a powerful technique in Angular that helps you build robust, scalable, and maintainable applications. By understanding the principles and patterns of DI, you can write cleaner and more testable code."}]
